export function Rtl({
  isRTL = {{isRTL}},
  title = "{{title}}",
  subtitle = "{{subtitle}}",
  accent = "{{accent}}",
}) {
  const dir = isRTL ? "rtl" : "ltr";
  return (
    <div dir={dir} style={{ font: "15px/1.6 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, padding: 12, borderRadius: 8, background: "#ffffff", border: "1px solid #24143018" }}>
        <span aria-hidden="true" style={{ width: 34, height: 34, borderRadius: 8, display: "grid", placeItems: "center", flexShrink: 0, background: accent }}>&#128230;</span>
        <div style={{ flex: 1 }}><strong style={{ display: "block" }}>{title}</strong><small style={{ color: "#24143099", fontSize: 12 }}>{subtitle}</small></div>
        <span aria-hidden="true" style={{ fontSize: 20, color: "#24143060", display: "inline-block", transform: isRTL ? "scaleX(-1)" : "scaleX(1)" }}>&rsaquo;</span>
      </div>
      <p style={{ margin: "10px 0 0", fontSize: 10, color: "#24143099" }}>dir="{dir}" &mdash; the row, icon order and chevron all flip with real direction, not a mirrored image.</p>
    </div>
  );
}
